+      e("span", { className: "q-number" }, `Question ${index + 1}.`),
+      " ",
+      question.prompt
+    ),
+    question.help
+      ? e("p", { id: helpId, className: "help-text" }, question.help)
+      : null,
+    e(
+      "div",
+      { className: "options", role: "presentation" },
+      question.options.map((opt) =>
+        e(Option, {
+          key: opt.value,
+          qId: question.id,
+          option: opt,
+          checked: selected.includes(opt.value),
+          onToggle,
+        })
+      )
+    )
+  );
+}
+
+function Results({ questions, answers }) {
+  const items = questions.map((q) => {
+    const picked = new Set(answers[q.id] || []);
+    const correct = new Set(q.options.filter((o) => o.correct).map((o) => o.value));
+    const isCorrect =
+      picked.size === correct.size && [...picked].every((v) => correct.has(v));
+    const correctLabels = q.options.filter((o) => o.correct).map((o) => o.label).join(", ");
+    return e(
+      "li",
+      { key: q.id },
+      e(
+        "span",
+        { className: isCorrect ? "correct" : "incorrect" },
+        isCorrect ? "Correct" : "Incorrect"
+      ),
+      ` — ${q.prompt} `,
+      !isCorrect ? e("em", null, `(Answer: ${correctLabels})`) : null
+    );
+  });
+  const score = items.filter((_, i) => {
+    const q = questions[i];
+    const picked = new Set(answers[q.id] || []);
+    const correct = new Set(q.options.filter((o) => o.correct).map((o) => o.value));
+    return picked.size === correct.size && [...picked].every((v) => correct.has(v));
+  }).length;
+  return e(
+    "section",
+    { className: "results", "aria-labelledby": "results-heading" },
+    e("h2", { id: "results-heading" }, `Your score: ${score} / ${questions.length}`),
+    e("ul", null, items)
+  );
+}
+
+function Quiz() {
+  const initial = useMemo(
+    () => Object.fromEntries(QUESTIONS.map((q) => [q.id, []])),
+    []
+  );
+  const [answers, setAnswers] = useState(initial);
+  const [submitted, setSubmitted] = useState(false);
+  const [status, setStatus] = useState("");
+
+  const onToggle = (qId) => (value) => {
+    setAnswers((prev) => {
+      const cur = new Set(prev[qId]);
+      if (cur.has(value)) cur.delete(value);
+      else cur.add(value);
+      return { ...prev, [qId]: [...cur] };
+    });
+  };
+
+  const onSubmit = (ev) => {
+    ev.preventDefault();
+    setSubmitted(true);
+    setStatus("Quiz submitted. See your results below.");
+  };
+
+  return e(
+    "div",
+    { className: "quiz-card" },
+    e(
+      "form",
+      { noValidate: true, onSubmit },
+      QUESTIONS.map((q, i) =>
+        e(Question, {
+          key: q.id,
+          question: q,
+          index: i,
+          selected: answers[q.id],
+          onToggle: onToggle(q.id),
+        })
+      ),
+      e(
+        "div",
+        { className: "actions" },
+        e("button", { type: "submit", className: "submit" }, "Submit answers"),
+        e(
+          "p",
+          { className: "status", role: "status", "aria-live": "polite" },
+          status
+        )
+      )
+    ),
+    submitted ? e(Results, { questions: QUESTIONS, answers }) : null
+  );
+}
+
+const root = ReactDOM.createRoot(document.getElementById("root"));
+root.render(e(Quiz));
+
')

